+@page "/notepad"
+@rendermode InteractiveServer
+@implements IAsyncDisposable
+@inject IJSRuntime JS
+
+<PageTitle>Notepad</PageTitle>
+
+<h1>Notepad</h1>
+
+<div class="mb-3">
+    <textarea class="form-control" rows="12" @bind="content" @bind:event="oninput"></textarea>
+</div>
+
+<div class="d-flex align-items-center gap-3 mb-3">
+    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
+    <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>
+    @if (lastSavedAt is not null)
+    {
+        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
+    }
+</div>
+
+<script type="module" src="@Assets["Components/Pages/Notepad.razor.js"]"></script>
+
+@code {
+    private const string StorageKey = "notepad-content";
+    private string content = string.Empty;
+    private string savedContent = string.Empty;
+    private DateTime? lastSavedAt;
+    private Timer? autoSaveTimer;
+    private IJSObjectReference? jsModule;
+    private DotNetObjectReference<Notepad>? dotNetRef;
+
+    protected override async Task OnAfterRenderAsync(bool firstRender)
+    {
+        if (!firstRender) return;
+
+        jsModule = await JS.InvokeAsync<IJSObjectReference>(
+            "import", Assets["Components/Pages/Notepad.razor.js"]);
+
+        dotNetRef = DotNetObjectReference.Create(this);
+        await jsModule.InvokeVoidAsync("init", dotNetRef);
+
+        var stored = await jsModule.InvokeAsync<string?>("load", StorageKey);
+        if (!string.IsNullOrEmpty(stored))
+        {
+            content = stored;
+            savedContent = stored;
+            StateHasChanged();
+        }
+
+        autoSaveTimer = new Timer(async _ =>
+        {
+            await InvokeAsync(AutoSaveAsync);
+        }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
+    }
+
+    private bool HasUnsavedChanges => content != savedContent;
+
+    [JSInvokable]
+    public bool CheckUnsavedChanges() => HasUnsavedChanges;
+
+    private async Task AutoSaveAsync()
+    {
+        if (!HasUnsavedChanges) return;
+        await SaveAsync();
+        StateHasChanged();
+    }
+
+    private async Task SaveNowAsync()
+    {
+        await SaveAsync();
+    }
+
+    private async Task SaveAsync()
+    {
+        if (jsModule is null) return;
+        await jsModule.InvokeVoidAsync("save", StorageKey, content);
+        savedContent = content;
+        lastSavedAt = DateTime.Now;
+    }
+
+    private async Task ClearAsync()
+    {
+        content = string.Empty;
+        savedContent = string.Empty;
+        lastSavedAt = null;
+        if (jsModule is not null)
+        {
+            await jsModule.InvokeVoidAsync("remove", StorageKey);
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (autoSaveTimer is not null)
+        {
+            await autoSaveTimer.DisposeAsync();
+        }
+        if (jsModule is not null)
+        {
+            try
+            {
+                await jsModule.InvokeVoidAsync("dispose");
+                await jsModule.DisposeAsync();
+            }
+            catch (JSDisconnectedException) { }
+        }
+        dotNetRef?.Dispose();
+    }
+}
+

